export const TAJ_BUILD_STAGES=[{id:"stage-wells",stepNumber:1,title:"1631–1632: Riverbank Site & Well Foundations",theme:"Engineering & Hydrogeology",summary:"Engineers excavated deep wells along the Yamuna riverbank, filling them with stone, mortar, and timber columns to create a subterranean flood-resistant platform.",details:"To stabilize the soft alluvial soil of Agra along the river, architects constructed a series of deep masonry wells lined with sal wood. The timber remains permanently preserved underground due to the high water table, creating an indestructible subterranean foundation raft.",materials:["Sal Wood","Rubble Masonry","Lime Mortar","Red Sandstone"],progressPercentage:16},{id:"stage-plinth",stepNumber:2,title:"1632–1635: Plinth Terrace & Sandstone Platform",theme:"Structural Architecture",summary:"A massive 300-meter-wide red sandstone terrace and elevated square marble plinth were raised above flood levels.",details:"The lower terrace was constructed using heavy red sandstone quarried from Tantpur and Fatehpur Sikri. Atop this sandstone terrace, a secondary 7-meter-high square platform clad in white Makrana marble was built to isolate the mausoleum from moisture.",materials:["Red Sandstone (Tantpur)","Makrana Marble (Rajasthan)"],progressPercentage:33},{id:"stage-core",stepNumber:3,title:"1635–1640: Octagonal Core & Brick Scaffolding",theme:"Masonry & Logistics",summary:"The main octagonal tomb structure was built around a brick core, serviced by a 15-kilometer rammed-earth slope for haulage.",details:"Instead of bamboo scaffolding, master builders constructed a massive brick scaffolding network matching the size of the tomb itself. Legend says Shah Jahan allowed peasants to keep any bricks they dismantled, clearing the scaffolding in a single day. A 15-km earth ramp allowed bullock teams to haul marble blocks to the upper levels.",materials:["Lakhori Bricks","Lime Mortar (Surkhi)","Pulleys & Ramps"],progressPercentage:50},{id:"stage-dome-minarets",stepNumber:4,title:"1640–1648: Double-Dome & Tilted Minarets",theme:"Acoustics & Seismic Safety",summary:"Construction of the 35-meter inner acoustic vault, 44-meter outer onion dome, and four minarets engineered to tilt slightly outward.",details:"The double-dome design provides both an intimate inner ceiling scale and a majestic outer skyline presence. The four 40-meter minarets were deliberately constructed leaning outward at a slight angle (~2 degrees) so that in the event of a catastrophic earthquake, they would fall away from the main tomb.",materials:["Copper Finial","Makrana Marble Slabs","Iron Straps"],progressPercentage:68},{id:"stage-inlay",stepNumber:5,title:"1648–1650: Parchin Kari (Pietra Dura) & Calligraphy",theme:"Artistry & Geometry",summary:"Master artisans inlaid 28 varieties of gemstones into marble and carved Thuluth script Quranic verses that optically adjust for height.",details:"Calligrapher Amanat Khan designed Quranic inscriptions around the iwan arches, progressively enlarging the letters higher up so they appear uniform from ground view. Over 28 semi-precious stone types were sourced from across Asia.",materials:["Lapis Lazuli (Afghanistan)","Jade (China)","Turquoise (Tibet)","Carnelian (Arabia)","Jasper (Punjab)"],progressPercentage:85},{id:"stage-gardens",stepNumber:6,title:"1650–1653: Charbagh Paradise Gardens & Completion",theme:"Symbolism & Landscape Architecture",summary:"Completion of the four-quadrant Paradise garden, reflecting pool, mosque, and Jawab guest house.",details:"The Charbagh garden is divided into four quadrants representing the four rivers of Paradise mentioned in Quranic tradition (water, milk, wine, honey). The central elevated lotus pool (Al-Kawthar) mirrors the white marble monument across seasons.",materials:["Cypress Trees","Reflecting Basin","Red Sandstone Mosque"],progressPercentage:100}];export const TAJ_MATERIALS_ORIGINS=[{stone:"White Marble",origin:"Makrana, Rajasthan (India)",distanceKm:400,use:"Exterior cladding & domes"},{stone:"Lapis Lazuli",origin:"Badakhshan (Afghanistan)",distanceKm:1800,use:"Floral inlay leaves"},{stone:"Jade & Crystal",origin:"Hetian (China)",distanceKm:2500,use:"Center flowers & scrollwork"},{stone:"Turquoise",origin:"Tibet",distanceKm:1400,use:"Calligraphic accents"},{stone:"Carnelian",origin:"Yemen / Arabia",distanceKm:3200,use:"Red floral petals"},{stone:"Sapphire & Corundum",origin:"Sri Lanka",distanceKm:2200,use:"Intricate borders"}];export const HISTORICAL_MYTHS_FLAGGED=[{id:"myth-mutilation",claim:"Shah Jahan ordered the hands/eyes of artisans cut off after completion.",verdict:"DISPUTED / UNFOUNDED MYTH",statusClass:"myth-false",explanation:"Zero contemporary 17th-century Mughal historical records (such as Abdul Hamid Lahori's official court chronicle Badshahnama) mention any mutilation. On the contrary, craftsmen received generous pensions, land grants, and subsequently worked on building Shahjahanabad (Old Delhi) and the Red Fort."},{id:"myth-black-taj",claim:"Shah Jahan planned a identical Black Marble Taj Mahal across the Yamuna.",verdict:"DISPUTED / LEGENDARY MYTH",statusClass:"myth-false",explanation:'Popularized by European traveler Jean-Baptiste Tavernier in 1665. Archaeological excavations conducted by the Archaeological Survey of India (ASI) at Mahtab Bagh in the 1990s revealed that the "black marble" ruins were actually blackened white marble stones and reflections in the octagonal pool.'},{id:"myth-tejo-mahalaya",claim:"The Taj Mahal was originally an ancient Hindu temple called Tejo Mahalaya.",verdict:"DISPUTED / HISTORICALLY DEBUNKED",statusClass:"myth-false",explanation:"Thoroughly rejected by historians and legal rulings of Indian courts. Mughal land acquisition deeds (Farman) show Shah Jahan purchased the land plot from Raja Jai Singh of Amber in exchange for four other mansions in Agra."}];export function getActiveStageIndex(e,a){if(a<=0)return 0;const t=100/a,n=Math.floor(e/t);return Math.max(0,Math.min(a-1,n))}export function filterMaterials(e,a){if(!a||""===a.trim())return[...e];const t=a.toLowerCase();return e.filter(e=>e.stone.toLowerCase().includes(t)||e.origin.toLowerCase().includes(t)||e.use.toLowerCase().includes(t))}export function getTajConstructionStats(){return{constructionPeriod:"1631 – 1653 (22 Years)",workforceEstimate:"~20,000 Craftsmen",chiefArchitect:"Ustad Ahmad Lahori",totalCostHistoric:"~32 Million Rupees (c. 1653)",materialsOriginsCount:TAJ_MATERIALS_ORIGINS.length,buildStagesCount:TAJ_BUILD_STAGES.length}}"undefined"!=typeof window&&"undefined"!=typeof document&&document.addEventListener("DOMContentLoaded",()=>{initTajScrollytelling()});export function initTajScrollytelling(){const e=document.getElementById("scrollytellingContainer"),a=document.getElementById("stageDetailsCard"),t=document.getElementById("tajProgressBar"),n=document.querySelectorAll(".taj-layer-group"),r=document.getElementById("materialsGrid"),i=document.getElementById("materialSearch");function s(e){const r=TAJ_BUILD_STAGES[e]||TAJ_BUILD_STAGES[0];t&&(t.style.width=`${r.progressPercentage}%`),n&&n.length>0&&n.forEach((a,t)=>{t<=e?a.classList.add("visible-layer"):a.classList.remove("visible-layer")}),a&&(a.innerHTML=`\n        <div class="stage-badge">Step ${r.stepNumber} of 6</div>\n        <h2 class="stage-title">${r.title}</h2>\n        <div class="stage-theme">📍 Focus: ${r.theme}</div>\n        <p class="stage-summary">${r.summary}</p>\n        <div class="stage-details-box">\n          <h4>Architectural & Engineering Deep-Dive</h4>\n          <p>${r.details}</p>\n        </div>\n        <div class="stage-materials-tags">\n          <strong>Key Materials & Tools:</strong>\n          <div class="tags-container">\n            ${r.materials.map(e=>`<span class="mat-tag">${e}</span>`).join("")}\n          </div>\n        </div>\n      `)}function o(e){r&&(r.innerHTML=e.map(e=>`\n      <div class="material-card">\n        <div class="mat-name">💎 ${e.stone}</div>\n        <div class="mat-origin">📍 Origin: ${e.origin}</div>\n        <div class="mat-distance">🚗 Transport Distance: ~${e.distanceKm} km</div>\n        <p class="mat-use">${e.use}</p>\n      </div>\n    `).join(""))}e&&(window.addEventListener("scroll",()=>{const a=e.getBoundingClientRect(),t=window.innerHeight,n=a.height-t;if(n>0){const e=Math.max(0,-a.top);s(getActiveStageIndex(Math.max(0,Math.min(100,e/n*100)),TAJ_BUILD_STAGES.length))}}),i&&i.addEventListener("input",e=>{o(filterMaterials(TAJ_MATERIALS_ORIGINS,e.target.value))}),s(0),o(TAJ_MATERIALS_ORIGINS))}